    public List<String[]> gameInstances()throws SQLException{List<String[]> out=new java.util.ArrayList<>();try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT mode,instance_no,world_set FROM game_instances ORDER BY mode,instance_no");ResultSet r=s.executeQuery()){while(r.next())out.add(new String[]{r.getString(1),String.valueOf(r.getInt(2)),r.getString(3)});}return out;}
    public void rememberWorldSet(String base,String overworld,String nether,String end)throws SQLException{try(Connection c=connection()){c.setAutoCommit(false);try(PreparedStatement a=c.prepareStatement("INSERT INTO plugin_worlds(name,environment) VALUES(?,?) ON CONFLICT(name) DO UPDATE SET environment=EXCLUDED.environment");PreparedStatement b=c.prepareStatement("INSERT INTO plugin_world_sets(name,overworld,nether,end_world) VALUES(?,?,?,?) ON CONFLICT(name) DO UPDATE SET overworld=EXCLUDED.overworld,nether=EXCLUDED.nether,end_world=EXCLUDED.end_world")){String[] names={overworld,nether,end};String[] envs={"NORMAL","NETHER","THE_END"};for(int i=0;i<3;i++){a.setString(1,names[i]);a.setString(2,envs[i]);a.addBatch();}a.executeBatch();b.setString(1,base);b.setString(2,overworld);b.setString(3,nether);b.setString(4,end);b.executeUpdate();c.commit();}catch(SQLException ex){c.rollback();throw ex;}}}
    public String[] worldSetFor(String world)throws SQLException{try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT name,overworld,nether,end_world FROM plugin_world_sets WHERE overworld=? OR nether=? OR end_world=?")){s.setString(1,world);s.setString(2,world);s.setString(3,world);try(ResultSet r=s.executeQuery()){return r.next()?new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4)}:null;}}}
    public List<String[]> managedWorldSets()throws SQLException{List<String[]> out=new java.util.ArrayList<>();try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT name,overworld,nether,end_world FROM plugin_world_sets ORDER BY name");ResultSet r=s.executeQuery()){while(r.next())out.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4)});}return out;}
