    public void rememberWorld(String name,String environment)throws SQLException{try(Connection c=connection();PreparedStatement s=c.prepareStatement("INSERT INTO plugin_worlds(name,environment) VALUES(?,?) ON CONFLICT(name) DO UPDATE SET environment=EXCLUDED.environment")){s.setString(1,name);s.setString(2,environment);s.executeUpdate();}}
    public void forgetWorld(String name)throws SQLException{try(Connection c=connection();PreparedStatement s=c.prepareStatement("DELETE FROM plugin_worlds WHERE name=?")){s.setString(1,name);s.executeUpdate();}}
    public List<String[]> managedWorlds()throws SQLException{List<String[]> worlds=new java.util.ArrayList<>();try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT name,environment FROM plugin_worlds ORDER BY name");ResultSet r=s.executeQuery()){while(r.next())worlds.add(new String[]{r.getString(1),r.getString(2)});}return worlds;}
